mapper.select:
select

from refund_order as mt
left join `order` o on o.id = mt.order_id
left join shop s on s.id = mt.merchant_id

    and mt.id = #{id}
     and mt.merchant_id = #{merchantId}
     and mt.order_id = #{orderId}
     and mt.refund_sso_id = #{refundSsoId}
     and mt.transaction_id = #{transactionId}
     and mt.refund_amount = #{refundAmount}
     and mt.refund_currency_id = #{refundCurrencyId}
     and mt.status = #{status}
     and mt.remaining_refundable_amount = #{remainingRefundableAmount}
     and mt.fail_reason = #{failReason}

     AND mt.create_at >= #{beginTime}
     AND mt.create_at < DATE_ADD(#{endTime}, INTERVAL 1 DAY)

        AND mt.id in

            #{id}



order by mt.id desc

SELECT DATE(create_at) AS date, COUNT(*) AS cnt
FROM refund_order


        merchant_id = #{merchantId}


        AND create_at BETWEEN #{startTime} AND #{endTime}


GROUP BY DATE(create_at)
ORDER BY date

SELECT DATE(create_at) AS date, COALESCE(SUM(refund_amount), 0) AS amount
FROM refund_order


        merchant_id = #{merchantId}


        AND create_at BETWEEN #{startTime} AND #{endTime}


GROUP BY DATE(create_at)
ORDER BY date
